# rnd-kb-tooling/src/kb_tools/lint.py — sketch
import re
from datetime import date
from pathlib import Path

import yaml
from pydantic import ValidationError

from kb_tools.schema import Page

FRONTMATTER = re.compile(r"\A---\n(.*?)\n---\n", re.DOTALL)
REL_LINK = re.compile(r"\]\((?!https?://|#)([^)#\s]+)")

def lint_page(path: Path, owners: set[str], repos: dict[str, Path]) -> list[str]:
    text = path.read_text()
    match = FRONTMATTER.match(text)
    if not match:
        return [f"{path}:1: missing frontmatter (copy templates/page.md)"]
    try:
        page = Page.model_validate(yaml.safe_load(match.group(1)))
    except ValidationError as err:
        return [f"{path}:1: {'.'.join(map(str, e['loc']))}: {e['msg']}" for e in err.errors()]
    problems = []
    if page.owner not in owners:
        problems.append(f"{path}:1: owner {page.owner} is not in OWNERS.yml")
    if page.reviewed > date.today():
        problems.append(f"{path}:1: reviewed date is in the future")
    for target in REL_LINK.findall(text):
        if not (path.parent / target).resolve().is_file():
            problems.append(f"{path}: link to a missing page: {target}")
    for item in page.applies_to:
        repo, pattern = item.split(":", 1)
        if repo in repos and next(repos[repo].glob(pattern), None) is None:
            problems.append(f"{path}:1: applies_to {item} matches no file in {repo}")
    return problems

# rnd-kb-tooling/src/kb_tools/ingest_collect.py — finds this week's news per page; no model calls
import fnmatch
import json
import subprocess
from collections import defaultdict


def gh(*args: str) -> list[str]:
    return subprocess.run(["gh", "api", *args], capture_output=True, text=True, check=True).stdout.splitlines()


def merged_prs(since: str) -> list[dict]:
    query = f"repo:RhinoHealth/fcp is:pr is:merged merged:>={since}"
    lines = gh("-X", "GET", "search/issues", "-f", f"q={query}", "--paginate",
               "--jq", ".items[] | {number, title, url: .html_url}")
    return [json.loads(line) for line in lines]


def collect(index: list[dict], since: str, epics: list[dict]) -> dict:
    work, unmatched = defaultdict(lambda: {"prs": [], "epics": []}), []
    for pr in merged_prs(since):
        files = gh(f"repos/RhinoHealth/fcp/pulls/{pr['number']}/files", "--paginate", "--jq", ".[].filename")
        pages = [p["path"] for p in index
                 if any(g.startswith("fcp:") and fnmatch.filter(files, g[4:]) for g in p["applies_to"])]
        for path in pages:
            work[path]["prs"].append(pr)
        if not pages:
            unmatched.append(pr)
    for epic in epics:  # from read-only JQL: epics moved to Done since `since`
        pages = [p["path"] for p in index if epic["key"] in p["sources"]]
        for path in pages:
            work[path]["epics"].append(epic)
        if not pages:
            unmatched.append(epic)
    return {"pages": work, "unmatched": unmatched}

